        public void DeepCopyIn(
            IMessage item,
            IMessageGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            base.DeepCopyIn(
                (IFallout76MajorRecord)item,
                (IFallout76MajorRecordGetter)rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.EDID) ?? true))
            {
                item.EDID = rhs.EDID;
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.DESC) ?? true))
            {
                item.DESC = rhs.DESC?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.FULL) ?? true))
            {
                item.FULL = rhs.FULL?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.Icon) ?? true))
            {
                item.Icon.SetTo(rhs.Icon.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.Quest) ?? true))
            {
                item.Quest.SetTo(rhs.Quest.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.DNAM) ?? true))
            {
                item.DNAM = rhs.DNAM;
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.XFLG) ?? true))
            {
                item.XFLG = rhs.XFLG;
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.TNAM) ?? true))
            {
                item.TNAM = rhs.TNAM;
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.SNAM) ?? true))
            {
                item.SNAM = rhs.SNAM;
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.NNAM) ?? true))
            {
                item.NNAM = rhs.NNAM?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.Conditions) ?? true))
            {
                errorMask?.PushIndex((int)Message_FieldIndex.Conditions);
                try
                {
                    if ((rhs.Conditions != null))
                    {
                        item.Conditions = 
                            rhs.Conditions
                            .Select(r =>
                            {
                                return r.DeepCopy(
                                    errorMask: errorMask,
                                    default(TranslationCrystal));
                            })
                            .ToExtendedList<Condition>();
                    }
                    else
                    {
                        item.Conditions = null;
                    }
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.ITXT) ?? true))
            {
                item.ITXT = rhs.ITXT;
            }
            if ((copyMask?.GetShouldTranslate((int)Message_FieldIndex.MBNR) ?? true))
            {
                item.MBNR = rhs.MBNR;
            }
            DeepCopyInCustom(
                item: item,
                rhs: rhs,
                errorMask: errorMask,
                copyMask: copyMask,
                deepCopy: deepCopy);
        }
        
